import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Rules:
    - Each line is split on its first "=", so values may contain "=".
    - Whitespace around the name and around the value is stripped.
    - Blank lines, lines whose first non-space character is "#", and
      lines without "=" are ignored.
    - Lines with an empty name (e.g. "=x") are ignored, so key "" always
      yields "".
    - Key matching is exact and case-sensitive.
    - If the key appears more than once, the last occurrence wins.
    - Returns "" when the key is absent. A key present with an empty
      value also yields "".
    - Lines may end in "\\n" or "\\r\\n".
    - Never reads files; only `text` is consulted.
    """
    result = ""
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        name = name.strip()
        if not name:
            continue
        if name == key:
            result = value.strip()
    return result


def test_basic_lookup() -> None:
    text = "host=example.com\nport=8080\n"
    assert config_value(text, "host") == "example.com"
    assert config_value(text, "port") == "8080"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "c") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =   value with spaces  \n", "name") == "value with spaces"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=1\n\n   # a=2\na=3\n"
    assert config_value(text, "a") == "3"


def test_commented_key_not_found() -> None:
    assert config_value("# a=1", "a") == ""


def test_lines_without_equals_ignored() -> None:
    text = "garbage\na=1\nmore garbage"
    assert config_value(text, "a") == "1"
    assert config_value(text, "garbage") == ""


def test_duplicate_key_last_wins() -> None:
    assert config_value("a=1\nb=2\na=3", "a") == "3"


def test_case_sensitive() -> None:
    assert config_value("Key=v", "key") == ""
    assert config_value("Key=v", "Key") == "v"


def test_exact_match_not_prefix() -> None:
    text = "ab=1\na=2"
    assert config_value(text, "a") == "2"
    assert config_value("ab=1", "a") == ""


def test_crlf_line_endings() -> None:
    text = "a=1\r\nb=2\r\n"
    assert config_value(text, "a") == "1"
    assert config_value(text, "b") == "2"


def test_no_trailing_newline() -> None:
    assert config_value("a=1\nb=2", "b") == "2"


def test_empty_name_line_ignored() -> None:
    assert config_value("=x\na=1", "") == ""


def test_empty_key_argument() -> None:
    assert config_value("a=1", "") == ""


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("a=1", "a", "1"),
        ("a = 1", "a", "1"),
        ("\ta\t=\t1\t", "a", "1"),
        ("x=1\ny=2", "y", "2"),
        ("x=1", "y", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected
